actions.script:
def org = ec.user.getPreference('ACTIVE_ORGANIZATION')
if (!org || org == '_NA_') { ec.message.addError('Select your company first.'); return }
def prod = ec.entity.find('mantle.product.Product').condition('productId', productId).disableAuthz().one()
if (prod == null || prod.ownerPartyId != org) { ec.message.addError('Product not found.'); return }
if (facilityId) {
    def fac = ec.entity.find('mantle.facility.Facility').condition('facilityId', facilityId).disableAuthz().one()
    if (fac == null || fac.ownerPartyId != org) { ec.message.addError('Store not found.'); return }
}
if (quantity == null || quantity <= 0) { ec.message.addError('Quantity to produce must be more than zero.'); return }

def now = java.time.LocalDate.now()
def fysSetting = ec.entity.find("zenith.erp.base.CompanySettings").condition("organizationPartyId", ec.user.getPreference("ACTIVE_ORGANIZATION")).condition("settingKey", "FY_START_MONTH").one()
int fyStartMonth = fysSetting ? (fysSetting.settingValue as int) : 4
int fyStart = now.monthValue >= fyStartMonth ? now.year : now.year - 1
def fy = "${fyStart}-${((fyStart+1) % 100).toString().padLeft(2, '0')}"
context.fyStr = fy

def seq = 1
if (woList) {
    def lastNum = woList[0].workOrderNumber
    def parts = lastNum.split('/')
    if (parts.length >= 3) seq = (parts[2] as Integer) + 1
}
context.workOrderNumber = "WO/${fyStr}/${seq.toString().padLeft(5, '0')}"

allowed = false
if (requireWrite && ec.service.sync().name('zenith.base.SecurityServices.check#ModuleWriteAccess')
        .parameters([moduleId:'manufacturing']).disableAuthz().call()?.canWrite != true) {
    ec.message.addError("You don't have permission to change manufacturing records."); return
}
def wo = ec.entity.find('zenith.erp.manufacturing.WorkOrder').condition('workOrderId', workOrderId).disableAuthz().one()
def woProd = wo ? ec.entity.find('mantle.product.Product').condition('productId', wo.productId).disableAuthz().one() : null
boolean isAdmin = ec.user.isInGroup('ADMIN')
def org = ec.user.getPreference('ACTIVE_ORGANIZATION')
if (!org || org == '_NA_') {
    if (!isAdmin) { ec.message.addError('Select your company first.'); return }
    org = woProd?.ownerPartyId
}
if (wo == null || (!isAdmin && woProd?.ownerPartyId != org)) { ec.message.addError('Work order not found.'); return }
organizationPartyId = org
allowed = true

if (quantity == 0) return
def org = organizationPartyId
def fmt = { v -> ((v ?: 0) as BigDecimal).stripTrailingZeros().toPlainString() }
def facility = ec.entity.find('mantle.facility.Facility').condition('facilityId', facilityId).disableAuthz().one()
// Lock order Product -> Asset lots, exactly as issue#PosStock, so a POS checkout and this move can't deadlock.
def product = ec.entity.find('mantle.product.Product').condition('productId', productId).forUpdate(true).disableAuthz().one()
// Fail closed: the store and the material must both belong to the acting org.
if (facility == null || facility.ownerPartyId != org || product == null || (product.ownerPartyId && product.ownerPartyId != org)) {
    ec.message.addError("This work order's store or material belongs to another company."); return
}
def lots = ec.entity.find('mantle.product.asset.Asset').condition('ownerPartyId', org)
    .condition('productId', productId).condition('facilityId', facilityId).condition('assetTypeEnumId', 'AstTpInventory')
    .orderBy('assetId').forUpdate(true).disableAuthz().list()
def ledger = { asset, BigDecimal diff ->
    def wasDisabled = ec.artifactExecution.disableEntityEca()
    try {
        ec.service.sync().name('create#mantle.product.asset.AssetDetail').parameters([
            assetId:asset.assetId, productId:productId, effectiveDate:ec.user.nowTimestamp,
            quantityOnHandDiff:diff, availableToPromiseDiff:diff, description:reason]).call()
    } finally { if (!wasDisabled) ec.artifactExecution.enableEntityEca() }
}
def change = { asset, BigDecimal diff ->
    asset.quantityOnHandTotal = ((asset.quantityOnHandTotal ?: 0) as BigDecimal) + diff
    asset.availableToPromiseTotal = ((asset.availableToPromiseTotal ?: 0) as BigDecimal) + diff
    asset.update()
    ledger(asset, diff)
}
def newLot = {
    def a = ec.entity.makeValue('mantle.product.asset.Asset').setFields([assetTypeEnumId:'AstTpInventory',
        statusId:'AstAvailable', ownerPartyId:org, productId:productId, facilityId:facilityId, hasQuantity:'Y',
        quantityOnHandTotal:0, availableToPromiseTotal:0], true, null, null)
    a.setSequencedIdPrimary(); a.create(); a
}
if (quantity < 0) { change(lots ? lots[0] : newLot(), -quantity); return }

def onHand = lots.inject(BigDecimal.ZERO) { sum, a -> sum + ((a.quantityOnHandTotal ?: 0) as BigDecimal) }
if (facility.assetAllowIssueOverQoh != 'Y' && quantity > onHand) {
    ec.message.addError('Only ' + fmt(onHand) + ' of ' + (product.productName ?: productId) + ' in stock at ' +
        (facility.facilityName ?: facilityId) + ', short by ' + fmt(quantity - onHand) + '. Receive or transfer stock first.')
    return
}
def remaining = quantity
lots.each { lot ->
    def qoh = (lot.quantityOnHandTotal ?: 0) as BigDecimal
    if (remaining <= 0 || qoh <= 0) return
    def taken = remaining.min(qoh)
    change(lot, -taken)
    remaining -= taken
}
// Only reached when the store explicitly allows issuing over stock.
if (remaining > 0) change(lots ? lots[0] : newLot(), -remaining)

// Raw materials leave stock: used (actual) + wasted (owner's rule). The form re-saves running TOTALS, so only
// the change since the last save moves stock. Stock-tracked materials only (same rule as POS), at the work
// order's facility, owned by the acting org. A work order with no facility only records the quantities.
def newActual = (actualQuantity ?: 0) as BigDecimal
def newWasted = (wastedQuantity ?: 0) as BigDecimal
if (newActual < 0 || newWasted < 0) { ec.message.addError("Used and wasted quantities can't be negative."); return }

// Access first, on every save (not only stock-moving ones): write permission + the work order's org.
def acc = ec.service.sync().name('zenith.manufacturing.ManufacturingServices.assert#WorkOrderAccess')
    .parameters([workOrderId:workOrderId]).call()
if (!acc?.allowed) return
def org = acc.organizationPartyId
def wo = ec.entity.find('zenith.erp.manufacturing.WorkOrder').condition('workOrderId', workOrderId).disableAuthz().one()
if (!(wo.statusId in ['WoReleased', 'WoInProgress', 'WoCompleted'])) {
    ec.message.addError('Release the work order before recording material use.'); return
}

// for-update: two fast Save clicks can't both read the old totals and move the same delta twice
def wom = ec.entity.find('zenith.erp.manufacturing.WorkOrderMaterial').condition('workOrderId', workOrderId)
    .condition('materialSeqId', materialSeqId).forUpdate(true).one()
if (wom == null) { ec.message.addError('Material line not found.'); return }
def delta = (newActual + newWasted) - (((wom.actualQuantity ?: 0) as BigDecimal) + ((wom.wastedQuantity ?: 0) as BigDecimal))
def issued = (wom.issuedQuantity ?: 0) as BigDecimal

// Lock the material Product row like POS issue does (material line -> Product -> Asset; no deadlock with POS).
def matProd = wom.productId ? ec.entity.find('mantle.product.Product').condition('productId', wom.productId).forUpdate(true).one() : null
BigDecimal move = BigDecimal.ZERO   // > 0 takes stock out, < 0 puts it back
if (wo.facilityId && matProd?.inventoryTracked == 'Y' && delta != 0) {
    // A downward correction returns at most what this line actually issued, so lines saved before stock
    // issuing existed (issuedQuantity null) can never create phantom stock.
    move = delta > 0 ? delta : -((-delta).min(issued))
}
if (move != 0) {
    ec.service.sync().name('zenith.manufacturing.ManufacturingServices.move#WorkOrderMaterialStock').parameters([
        organizationPartyId:org, productId:wom.productId, facilityId:wo.facilityId, quantity:move,
        reason:('Work order ' + (wo.workOrderNumber ?: workOrderId) + ' material ' + (move > 0 ? 'used' : 'returned'))]).call()
    if (ec.message.hasError()) return
}
ec.service.sync().name('update#zenith.erp.manufacturing.WorkOrderMaterial').parameters([
    workOrderId:workOrderId, materialSeqId:materialSeqId, actualQuantity:newActual, wastedQuantity:newWasted,
    issuedQuantity:(move != 0 ? issued + move : wom.issuedQuantity)]).call()

def acc = ec.service.sync().name('zenith.manufacturing.ManufacturingServices.assert#WorkOrderAccess')
    .parameters([workOrderId:workOrderId]).call()
if (!acc?.allowed) return
def wo = ec.entity.find('zenith.erp.manufacturing.WorkOrder').condition('workOrderId', workOrderId).forUpdate(true).disableAuthz().one()
if (!(wo.statusId in ['WoDraft', 'WoReleased'])) {
    ec.message.addError('Only a Draft or Released work order can be cancelled.'); return
}
// productId order: the same order a POS cart locks products in, so the two can't deadlock.
def lines = ec.entity.find('zenith.erp.manufacturing.WorkOrderMaterial').condition('workOrderId', workOrderId)
    .orderBy('productId').orderBy('materialSeqId').forUpdate(true).list()
for (wom in lines) {
    def issued = (wom.issuedQuantity ?: 0) as BigDecimal
    // Only USED material goes back. Cap at what was issued minus what was wasted, so an old line whose
    // used quantity was never issued can't hand back its wasted quantity as stock.
    def back = ((wom.actualQuantity ?: 0) as BigDecimal).min((issued - ((wom.wastedQuantity ?: 0) as BigDecimal)).max(BigDecimal.ZERO))
    if (back > 0 && wo.facilityId) {
        ec.service.sync().name('zenith.manufacturing.ManufacturingServices.move#WorkOrderMaterialStock').parameters([
            organizationPartyId:acc.organizationPartyId, productId:wom.productId, facilityId:wo.facilityId,
            quantity:-back, reason:('Work order ' + (wo.workOrderNumber ?: workOrderId) + ' cancelled, material returned')]).call()
        if (ec.message.hasError()) return
        wom.issuedQuantity = issued - back
    }
    // The used quantity went back, so the line no longer shows it as used. Wasted stays recorded.
    wom.actualQuantity = 0
    wom.update()
}
wo.statusId = 'WoCancelled'
wo.update()

def now = java.time.LocalDate.now()
def fysSetting = ec.entity.find("zenith.erp.base.CompanySettings").condition("organizationPartyId", ec.user.getPreference("ACTIVE_ORGANIZATION")).condition("settingKey", "FY_START_MONTH").one()
int fyStartMonth = fysSetting ? (fysSetting.settingValue as int) : 4
int fyStart = now.monthValue >= fyStartMonth ? now.year : now.year - 1
def fy = "${fyStart}-${((fyStart+1) % 100).toString().padLeft(2, '0')}"
context.fyStr = fy

def seq = 1
if (jwList) {
    def parts = jwList[0].jobWorkNumber.split('/')
    if (parts.length >= 3) seq = (parts[2] as Integer) + 1
}
context.jobWorkNumber = "JW/${fyStr}/${seq.toString().padLeft(5, '0')}"
context.challanNumber = "DC/${fyStr}/${seq.toString().padLeft(5, '0')}"

def now = java.time.LocalDate.now()
def years = jw.isCapitalGoods == 'Y' ? 3 : 1
context.expectedReturn = java.sql.Date.valueOf(now.plusYears(years))
